package pl.zagranietyper;import com.fasterxml.jackson.databind.ObjectMapper;import pl.zagranietyper.config.*;import pl.zagranietyper.fixture.ApiFootballClient;import pl.zagranietyper.repository.*;import pl.zagranietyper.service.FootballCompetitionProgressionNormalizer;import java.util.*;
public final class FootballCompetitionProgressionBackfillMain {private FootballCompetitionProgressionBackfillMain(){}public static void main(String[]a){if(a.length!=1||!a[0].equals("--run"))throw new IllegalArgumentException("--run");var db=new Database(AppConfig.fromEnvironment());db.initializeSchema();var candidates=new FootballTeamToAdvanceCandidateRepository(db).find();var targets=new TreeSet<Key>();for(var c:candidates)targets.add(new Key(c.leagueId(),c.season()));var repo=new FootballCompetitionProgressionRepository(db);var client=new ApiFootballClient(ApiFootballConfig.fromEnvironment(),new ObjectMapper());var norm=new FootballCompetitionProgressionNormalizer();int complete=0,failed=0;for(var k:targets){if(repo.status(k.league,k.season)==pl.zagranietyper.model.FootballCompetitionProgressionSnapshot.Status.COMPLETE){complete++;continue;}var s=norm.normalize(client.fetchCompetitionFixtures(k.league,k.season));repo.store(s);if(s.status()==pl.zagranietyper.model.FootballCompetitionProgressionSnapshot.Status.COMPLETE)complete++;else failed++;System.out.println("league="+k.league+" season="+k.season+" status="+s.status()+" fixtures="+s.fixtures().size());}System.out.println("targets="+targets.size()+" complete="+complete+" failed="+failed);}record Key(long league,int season)implements Comparable<Key>{public int compareTo(Key x){int c=Long.compare(league,x.league);return c!=0?c:Integer.compare(season,x.season);}}}
